indirect enum Document {
    case text(String), line, softline, hardline, breakParent, suffix(String), ifBreak(String, String)
    case group(Int, Document), nest(Int, Document), align(Document), concat([Document])
    var forced: Bool {
        switch self {
            case .hardline, .breakParent: return true;
            case .concat(let parts): return parts.contains {
                $0.forced
            };
            case .group(_, let child), .nest(_, let child), .align(let child): return child.forced;
            default: return false
        }
    }
    var groupCount: Int {
        switch self {
            case .group(_, let child): return 1 + child.groupCount;
            case .nest(_, let child), .align(let child): return child.groupCount;
            case .concat(let parts): return parts.reduce(0) {
                $0 + $1.groupCount
            };
            default: return 0
        }
    }
}
func text(_ value: String) -> Document {
    .text(value)
}
func concat(_ parts: [Document]) -> Document {
    var result: [Document] = []
    func flatten(_ document: Document) {
        if case .concat(let children) = document {
            for child in children {
                flatten(child)
            }
        }
        else if case .text(let string) = document {
            if string.isEmpty {
                return
            }
            if let last = result.last, case .text(let previous) = last {
                result[result.count - 1] = .text(previous + string)
            }
            else {
                result.append(document)
            }
        } else {
            result.append(document)
        }
    }
    for part in parts {
        flatten(part)
    }
    return result.isEmpty ? .text("") : result.count == 1 ? result[0] : .concat(result)
}
func nest(_ n: Int, _ child: Document) -> Document {
    .nest(n, child)
}
func align(_ child: Document) -> Document {
    .align(child)
}
func line() -> Document {
    .line
}
func softline() -> Document {
    .softline
}
func hardline() -> Document {
    .hardline
}
func suffix(_ value: String) -> Document {
    .suffix(value)
}
func breakParent() -> Document {
    .breakParent
}
func ifBreak(_ broken: String, _ flat: String) -> Document {
    .ifBreak(broken, flat)
}
final class DocBuilder {
    var next = 0
    func group(_ child: Document) -> Document {
        let id = next;
        next += 1;
        return .group(id, child)
    }
}

import Foundation
struct SourceError: Error {
    let line: Int, column: Int, message: String
}
struct Comment {
    let text: String, line: Int, column: Int, blank: Int, lineComment: Bool;
    var own = false
}
struct Token {
    let text: String, kind: String, line: Int, column: Int, blank: Int
    var leading: [Comment] = [], trailing: [Comment] = []
}
struct Lexed {
    var tokens: [Token] = [], comments: [Comment] = [], order: [(Bool, Int)] = []
}
enum Lexer {
    static func letter(_ c: UInt8) -> Bool {
        (65...90).contains(c) || (97...122).contains(c)
    }
    static func digit(_ c: UInt8) -> Bool {
        (48...57).contains(c)
    }
    static func trim(_ text: String) -> String {
        String(text.reversed().drop(while: {
            $0 == " "
        }).reversed())
    }
    static func lex(_ lines: [String]) throws -> Lexed {
        var result = Lexed(), previous = 0
        for (row, line) in lines.enumerated() {
            let a = Array(line.utf8)
            var i = 0
            func string(_ start: Int, _ end: Int) -> String {
                String(bytes: a[start..<end], encoding: .ascii)!
            }
            while i < a.count {
                if a[i] == 32 {
                    i += 1;
                    continue
                }
                let start = i, lineNumber = row + 1, blank = max(0, lineNumber - previous - 1)
                func error(_ message: String) -> SourceError {
                    SourceError(line: lineNumber, column: start + 1, message: message)
                }
                if i + 1 < a.count && a[i] == 47 && a[i + 1] == 47 {
                    result.order.append((false, result.comments.count))
                    result.comments.append(Comment(text: trim(string(i, a.count)), line: lineNumber, column: i + 1, blank: blank, lineComment: true));
                    previous = lineNumber;
                    break
                }
                if i + 1 < a.count && a[i] == 47 && a[i + 1] == 42 {
                    var end = i + 2
                    while end + 1 < a.count && !(a[end] == 42 && a[end + 1] == 47) {
                        end += 1
                    }
                    if end + 1 >= a.count {
                        throw error("unterminated comment")
                    }
                    end += 2
                    result.order.append((false, result.comments.count))
                    result.comments.append(Comment(text: string(i, end), line: lineNumber, column: i + 1, blank: blank, lineComment: false));
                    previous = lineNumber;
                    i = end;
                    continue
                }
                let kind: String
                if letter(a[i]) || a[i] == 95 {
                    i += 1
                    while i < a.count && (letter(a[i]) || digit(a[i]) || a[i] == 95) {
                        i += 1
                    }
                    kind = ["int", "float", "bool", "string", "void", "if", "else", "while", "for", "return", "break", "continue", "true", "false", "switch", "case", "default"].contains(string(start, i)) ? "keyword" : "identifier"
                } else if digit(a[i]) {
                    i += 1
                    while i < a.count && digit(a[i]) {
                        i += 1
                    }
                    if i + 1 < a.count && a[i] == 46 && digit(a[i + 1]) {
                        i += 2;
                        while i < a.count && digit(a[i]) {
                            i += 1
                        }
                    }
                    kind = "number"
                } else if a[i] == 34 {
                    i += 1
                    var closed = false
                    while i < a.count {
                        if a[i] == 92 {
                            i += 2
                        }
                        else if a[i] == 34 {
                            i += 1;
                            closed = true;
                            break
                        }
                        else {
                            i += 1
                        }
                    }
                    if !closed {
                        throw error("unterminated string")
                    }
                    kind = "string"
                } else if i + 1 < a.count && ["<=", ">=", "==", "!=", "&&", "||", "+=", "-=", "*=", "/=", "%="].contains(string(i, i + 2)) {
                    i += 2;
                    kind = "symbol"
                }
                else if Array("+-*/%<>=!()[]{},;.?:".utf8).contains(a[i]) {
                    i += 1;
                    kind = "symbol"
                }
                else {
                    throw error("unexpected character '\(String(UnicodeScalar(a[i])))'")
                }
                result.order.append((true, result.tokens.count))
                result.tokens.append(Token(text: string(start, i), kind: kind, line: lineNumber, column: start + 1, blank: blank));
                previous = lineNumber
            }
        }
        result.tokens.append(Token(text: "", kind: "end", line: lines.count + 1, column: 1, blank: 0))
        return result
    }
}

import Foundation
struct Profile {
    var values: [String: String] = [:]
    func yes(_ key: String) -> Bool {
        values[key] == "yes"
    }
    func number(_ key: String) -> Int {
        Int(values[key]!)!
    }
    var kr: Bool {
        values["brace_style"] == "kr"
    }
}
func attach(_ lexed: Lexed) -> ([Token], Int) {
    var tokens = lexed.tokens
    for (k, entry) in lexed.order.enumerated() where !entry.0 {
        var comment = lexed.comments[entry.1]
        let previous = lexed.order[..<k].last {
            $0.0
        }?.1, next = lexed.order.dropFirst(k + 1).first {
            $0.0
        }?.1
        let nextLine: Int?
        if k + 1 < lexed.order.count {
            let entry = lexed.order[k + 1];
            nextLine = entry.0 ? tokens[entry.1].line : lexed.comments[entry.1].line
        }
        else {
            nextLine = nil
        }
        comment.own = comment.lineComment || (nextLine.map {
            $0 > comment.line
        } ?? true)
        let trailing = previous.map {
            tokens[$0].line == comment.line
        } == true && (next.map {
            tokens[$0].line > comment.line
        } ?? true)
        if trailing {
            tokens[previous!].trailing.append(comment)
        } else {
            tokens[next ?? tokens.count - 1].leading.append(comment)
        }
    }
    return (tokens, lexed.comments.count)
}
func checkComments(_ items: [SyntaxNode], _ tokens: [Token]) throws {
    var allowed: Set<Int> = [tokens.count - 1], tails: Set<Int> = []
    func walk(_ node: SyntaxNode) {
        switch node.kind {
            case "block": allowed.insert(node.tokens[1]);
            for child in node.children {
                allowed.insert(child.start)
            }
            case "switch":
            allowed.insert(node.tokens[4])
            for clause in node.children.dropFirst() {
                allowed.insert(clause.tokens[0]);
                for statement in clause.children.dropFirst(clause.kind == "case" ? 1 : 0) {
                    allowed.insert(statement.start)
                }
            }
            case "if":
            if node.children[1].kind != "block" {
                allowed.insert(node.children[1].start)
            }
            if node.children.count == 3 && node.children[2].kind != "block" && node.children[2].kind != "if" {
                allowed.insert(node.children[2].start)
            }
            case "while": if node.children[1].kind != "block" {
                allowed.insert(node.children[1].start)
            }
            case "for": if node.children[3].kind != "block" {
                allowed.insert(node.children[3].start)
            }
            case "params", "args", "initlist": for child in node.children {
                allowed.insert(child.start)
            };
            if let tail = node.trailing {
                tails.insert(tail)
            }
            default: break
        }
        for child in node.children {
            walk(child)
        }
    }
    for item in items {
        allowed.insert(item.start);
        walk(item)
    }
    for (i, token) in tokens.enumerated() {
        for comment in token.leading where comment.own && !allowed.contains(i) || tails.contains(i) {
            throw SourceError(line: comment.line, column: comment.column, message: "comment not allowed here")
        }
    }
}
final class Construction {
    var tokens: [Token]
    let originalTrailing: [Bool], profile: Profile, docs = DocBuilder()
    init(_ tokens: [Token], _ profile: Profile) {
        self.tokens = tokens;
        self.profile = profile;
        originalTrailing = tokens.map {
            !$0.trailing.isEmpty
        }
    }
    func space() -> Document {
        text(profile.yes("space_around_operators") ? " " : "")
    }
    func keywordSpace() -> Document {
        text(profile.yes("space_after_keyword") ? " " : "")
    }
    func operatorLine() -> Document {
        profile.yes("space_around_operators") ? line() : softline()
    }
    func separator(_ blank: Int) -> Document {
        concat((0...min(blank, profile.number("max_blank_lines"))).map {
            _ in hardline()
        })
    }
    func preblank(_ token: Int) -> Int {
        tokens[token].leading.first?.blank ?? tokens[token].blank
    }
    func comments(_ comments: [Comment], _ next: Int?) -> Document {
        var parts: [Document] = []
        for (i, comment) in comments.enumerated() {
            parts.append(text(comment.text))
            if let blank = i + 1 < comments.count ? comments[i + 1].blank : next {
                parts.append(comment.own ? separator(blank) : text(" "))
            }
        }
        return concat(parts)
    }
    func trailing(_ token: Int) -> Document {
        tokens[token].trailing.isEmpty ? text("") : suffix(tokens[token].trailing.map(\.text).joined(separator: " "))
    }
    func tokenWith(_ token: Int, _ leading: [Comment]) -> Document {
        concat([comments(leading, tokens[token].blank), text(tokens[token].text), trailing(token)])
    }
    func token(_ token: Int) -> Document {
        tokenWith(token, tokens[token].leading)
    }
    func group(_ child: Document) -> Document {
        docs.group(child)
    }
    func level(_ node: SyntaxNode) -> Int {
        node.kind == "conditional" ? 0 : node.kind == "binary" ? Parser.precedence(tokens[node.tokens[0]].text) : node.kind == "unary" ? 7 : 8
    }
    func open(_ node: SyntaxNode, _ level: Int) -> SyntaxNode {
        var current = node
        while profile.yes("remove_parens") && current.kind == "paren" && self.level(current.children[0]) >= level && tokens[current.tokens[0]].leading.isEmpty && tokens[current.tokens[1]].leading.isEmpty {
            let child = current.children[0], open = current.tokens[0], close = current.tokens[1], first = tokens[open].trailing, last = tokens[close].trailing
            tokens[open].trailing = [];
            tokens[close].trailing = []
            tokens[child.start].trailing = first + tokens[child.start].trailing
            tokens[child.end].trailing += last
            current = child
        }
        return current
    }
    func list(_ node: SyntaxNode) -> Document {
        let open = node.tokens[0], close = node.tokens.last!
        if node.children.isEmpty {
            return concat([token(open), token(close)])
        }
        let forced = originalTrailing[node.start..<node.end].contains(true)
        var inside = [softline()]
        for (i, child) in node.children.enumerated() {
            if i > 0 {
                inside += [token(node.tokens[i]), line()]
            }
            inside.append(node.kind == "params" ? parameter(child) : node.kind == "initlist" ? initializer(child) : expression(child, 0))
        }
        if node.kind == "initlist" {
            inside.append(ifBreak(",", ""));
            if let tail = node.trailing {
                inside.append(trailing(tail))
            }
        }
        return group(concat([forced ? breakParent() : text(""), token(open), nest(profile.number("indent"), concat(inside)), softline(), token(close)]))
    }
    func parameter(_ node: SyntaxNode) -> Document {
        var parts = [token(node.tokens[0]), text(" "), token(node.tokens[1])]
        for dimension in node.children {
            parts += [token(dimension.tokens[0]), token(dimension.tokens[1])]
        }
        return concat(parts)
    }
    func declaration(_ node: SyntaxNode) -> Document {
        var parts = [token(node.tokens[0]), text(" "), token(node.tokens[1])], initial: SyntaxNode?
        for child in node.children {
            if child.kind == "dimension" {
                parts.append(token(child.tokens[0]));
                if let expr = child.children.first {
                    parts.append(expression(expr, 0))
                };
                parts.append(token(child.tokens[1]))
            }
            else {
                initial = child
            }
        }
        for t in node.tokens.dropFirst(2) {
            if tokens[t].text == "=" {
                parts += [space(), token(t), space(), initializer(initial!)]
            }
            else {
                parts.append(token(t))
            }
        }
        return concat(parts)
    }
    func initializer(_ node: SyntaxNode) -> Document {
        node.kind == "initlist" ? list(node) : expression(node, 0)
    }
    func closing(_ token: Int) -> ([Comment], [Comment]) {
        let comments = tokens[token].leading, split = comments.lastIndex {
            $0.own
        }.map {
            $0 + 1
        } ?? 0
        return (Array(comments[..<split]), Array(comments[split...]))
    }
    func block(_ node: SyntaxNode) -> Document {
        let close = node.tokens[1], (h, g) = closing(close)
        if node.children.isEmpty && h.isEmpty {
            return concat([token(node.tokens[0]), tokenWith(close, g)])
        }
        var inside = [hardline()]
        for (i, statement) in node.children.enumerated() {
            if i > 0 {
                inside.append(separator(preblank(statement.start)))
            };
            inside.append(self.statement(statement))
        }
        if !h.isEmpty {
            if !node.children.isEmpty {
                inside.append(separator(h[0].blank))
            };
            inside.append(comments(h, nil))
        }
        return concat([token(node.tokens[0]), nest(profile.number("indent"), concat(inside)), hardline(), tokenWith(close, g)])
    }
    func body(_ node: SyntaxNode) -> Document {
        let separator = profile.kr ? text(" ") : hardline()
        if node.kind == "block" {
            return concat([separator, block(node)])
        }
        let document = statement(node)
        if profile.yes("add_braces") {
            return concat([separator, text("{"), nest(profile.number("indent"), concat([hardline(), document])), hardline(), text("}")])
        }
        return nest(profile.number("indent"), concat([hardline(), document]))
    }
    func simple(_ node: SyntaxNode) -> Document {
        if node.kind == "assign" {
            let left = expression(node.children[0], 0), right = expression(node.children[1], 0);
            return concat([left, space(), token(node.tokens[0]), space(), right])
        }
        return expression(node.children[0], 0)
    }
    func clause(_ node: SyntaxNode) -> Document {
        var parts = [token(node.tokens[0])]
        let first = node.kind == "case" ? 1 : 0
        if first == 1 {
            parts += [text(" "), expression(node.children[0], 0)]
        }
        parts.append(token(node.tokens[1]))
        if node.children.count > first {
            var statements = [hardline()]
            for (i, statement) in node.children.dropFirst(first).enumerated() {
                if i > 0 {
                    statements.append(separator(preblank(statement.start)))
                };
                statements.append(self.statement(statement))
            }
            parts.append(nest(profile.number("indent"), concat(statements)))
        }
        return concat(parts)
    }
    func statement(_ node: SyntaxNode) -> Document {
        switch node.kind {
            case "block": return block(node)
            case "decl": return declaration(node)
            case "statement": return concat([simple(node.children[0]), token(node.tokens[0])])
            case "break", "continue": return concat(node.tokens.map(token))
            case "return":
            var parts = [token(node.tokens[0])]
            if let expr = node.children.first {
                parts += [text(" "), expression(expr, 0)]
            }
            return concat(parts + [token(node.tokens[1])])
            case "while", "if":
            let condition = expression(node.children[0], 0), body = self.body(node.children[1])
            var parts = [token(node.tokens[0]), keywordSpace(), token(node.tokens[1]), condition, token(node.tokens[2]), body]
            if node.kind == "if" && node.children.count == 3 {
                parts.append(profile.kr && (node.children[1].kind == "block" || profile.yes("add_braces")) ? text(" ") : hardline());
                parts.append(token(node.tokens[3]))
                if node.children[2].kind == "if" {
                    parts += [text(" "), statement(node.children[2])]
                } else {
                    parts.append(self.body(node.children[2]))
                }
            }
            return concat(parts)
            case "for":
            var inner: [Document] = []
            let initial = node.children[0]
            if initial.kind != "empty" {
                inner.append(initial.kind == "decl" ? declaration(initial) : simple(initial))
            }
            inner.append(token(node.tokens[2]))
            if node.children[1].kind != "empty" {
                inner += [line(), expression(node.children[1], 0)]
            }
            inner.append(token(node.tokens[3]))
            if node.children[2].kind != "empty" {
                inner += [line(), simple(node.children[2])]
            }
            let group = self.group(align(concat(inner))), body = self.body(node.children[3])
            return concat([token(node.tokens[0]), keywordSpace(), token(node.tokens[1]), group, token(node.tokens[4]), body])
            case "switch":
            let close = node.tokens[4], (h, g) = closing(close), condition = expression(node.children[0], 0)
            var parts = [token(node.tokens[0]), keywordSpace(), token(node.tokens[1]), condition, token(node.tokens[2]), profile.kr ? text(" ") : hardline(), token(node.tokens[3])]
            if node.children.count > 1 || !h.isEmpty {
                var inside = [hardline()]
                for (i, clause) in node.children.dropFirst().enumerated() {
                    if i > 0 {
                        inside.append(separator(preblank(clause.start)))
                    };
                    inside.append(self.clause(clause))
                }
                if !h.isEmpty {
                    if node.children.count > 1 {
                        inside.append(separator(h[0].blank))
                    };
                    inside.append(comments(h, nil))
                }
                parts += [nest(profile.yes("indent_case_labels") ? profile.number("indent") : 0, concat(inside)), hardline()]
            }
            return concat(parts + [tokenWith(close, g)])
            default: preconditionFailure()
        }
    }
    func function(_ node: SyntaxNode) -> Document {
        let parameters = list(node.children[0]), block = self.block(node.children[1])
        return concat([token(node.tokens[0]), text(" "), token(node.tokens[1]), parameters, hardline(), block])
    }
    func postfix(_ node: SyntaxNode) -> Document {
        switch node.kind {
            case "call": return list(node.children[1])
            case "index": let index = expression(node.children[1], 0);
            return concat([token(node.tokens[0]), index, token(node.tokens[1])])
            case "member": return concat([token(node.tokens[0]), token(node.tokens[1])])
            default: preconditionFailure()
        }
    }
    func expression(_ original: SyntaxNode, _ required: Int) -> Document {
        let node = open(original, required)
        switch node.kind {
            case "atom": return token(node.tokens[0])
            case "paren": let inner = expression(node.children[0], 0);
            return concat([token(node.tokens[0]), inner, token(node.tokens[1])])
            case "unary": let operand = expression(node.children[0], 8);
            return concat([token(node.tokens[0]), operand])
            case "binary":
            let p = level(node)
            var current = node, entries: [(Int, SyntaxNode)] = []
            while current.kind == "binary" && level(current) == p {
                entries.append((current.tokens[0], current.children[1]));
                current = open(current.children[0], p)
            }
            let head = expression(current, p)
            var rest: [Document] = []
            for (op, right) in entries.reversed() {
                rest += [operatorLine(), token(op), space(), expression(right, p + 1)]
            }
            return group(concat([head, nest(profile.number("indent"), concat(rest))]))
            case "conditional":
            let head = expression(node.children[0], 1)
            var current = node, rest: [Document] = []
            while true {
                rest += [operatorLine(), token(current.tokens[0]), space(), expression(current.children[1], 0), operatorLine(), token(current.tokens[1]), space()]
                let next = open(current.children[2], 0)
                if next.kind == "conditional" {
                    rest.append(expression(next.children[0], 1));
                    current = next
                }
                else {
                    rest.append(expression(next, 0));
                    break
                }
            }
            return group(concat([head, nest(profile.number("indent"), concat(rest))]))
            case "call", "index", "member":
            var current = node, operations: [SyntaxNode] = []
            while ["call", "index", "member"].contains(current.kind) {
                let target = current.children[0];
                operations.append(current);
                current = open(target, 8)
            }
            var segments: [[SyntaxNode]] = [[]]
            for operation in operations.reversed() {
                if operation.kind == "member" {
                    segments.append([])
                };
                segments[segments.count - 1].append(operation)
            }
            let calls = segments.indices.dropFirst().filter {
                segments[$0].contains {
                    $0.kind == "call"
                }
            }
            var parts = [expression(current, 8)]
            if calls.count < 2 {
                for operation in segments.flatMap({
                    $0
                }) {
                    parts.append(postfix(operation))
                };
                return concat(parts)
            }
            let first = calls[0]
            for operation in segments[..<first].flatMap({
                $0
            }) {
                parts.append(postfix(operation))
            }
            var rest: [Document] = []
            for segment in segments[first...] {
                rest.append(softline());
                for operation in segment {
                    rest.append(postfix(operation))
                }
            }
            parts.append(nest(profile.number("indent"), concat(rest)))
            return group(concat(parts))
            default: preconditionFailure()
        }
    }
}
struct Formatted {
    let lines: [String], firstFunction: (String, Document)?, modes: [Int: String], comments: Int
}
func formatSource(_ lines: [String], _ profile: Profile) throws -> Formatted {
    let (tokens, commentCount) = attach(try Lexer.lex(lines)), items = try Parser.parse(tokens)
    try checkComments(items, tokens)
    let empty = items.isEmpty && tokens.last!.leading.isEmpty, builder = Construction(tokens, profile)
    var parts: [Document] = [], firstFunction: (String, Document)?
    for (i, node) in items.enumerated() {
        if i > 0 {
            parts.append(builder.separator(builder.preblank(node.start)))
        }
        let document = node.kind == "function" ? builder.function(node) : builder.declaration(node)
        if node.kind == "function" && firstFunction == nil {
            firstFunction = (builder.tokens[node.tokens[1]].text, document)
        }
        parts.append(document)
    }
    let closing = builder.tokens.last!.leading
    if !closing.isEmpty {
        if !items.isEmpty {
            parts.append(builder.separator(closing[0].blank))
        };
        parts.append(builder.comments(closing, nil))
    }
    if empty {
        return Formatted(lines: [], firstFunction: firstFunction, modes: [:], comments: commentCount)
    }
    let printed = Printer.print(concat(parts), profile.number("width"), profile.number("comment_column"))
    return Formatted(lines: printed.lines, firstFunction: firstFunction, modes: printed.modes, comments: commentCount)
}
struct Source {
    let header: String, name: String, profile: String;
    var lines: [String] = []
}
func inputs() -> ([String: Profile], [Source]) {
    var profiles: [String: Profile] = [:], current = ""
    for line in (try! String(contentsOfFile: "input/style.txt", encoding: .ascii)).split(separator: "\n") {
        if line.first == "[" {
            current = String(line.dropFirst().dropLast());
            profiles[current] = Profile()
        }
        else {
            let a = line.split(separator: "=", omittingEmptySubsequences: false).map(String.init);
            profiles[current, default: Profile()].values[a[0]] = a[1]
        }
    }
    var sources: [Source] = []
    let text = try! String(contentsOfFile: "input/sources.txt", encoding: .ascii)
    for line in text.components(separatedBy: "\n").dropLast() {
        if line.hasPrefix("=== ") {
            let a = line.split(separator: " ").map(String.init);
            sources.append(Source(header: line, name: a[1], profile: a[2]))
        }
        else {
            sources[sources.count - 1].lines.append(line)
        }
    }
    return (profiles, sources)
}
func write(_ name: String, _ lines: [String]) {
    try! FileManager.default.createDirectory(atPath: "output", withIntermediateDirectories: true)
    try! (lines.isEmpty ? "" : lines.joined(separator: "\n") + "\n").write(toFile: "output/" + name, atomically: false, encoding: .ascii)
}
func runProgram() {
    let (profiles, sources) = inputs()
    var formatted: [String] = [], idempotency: [String] = [], diagnostics: [String] = [], docTree: [String] = [], changes: [String] = []
    for source in sources {
        let profile = profiles[source.profile]!, original = source.lines.map(Lexer.trim)
        formatted.append(source.header);
        docTree.append("=== \(source.name)");
        changes.append("=== \(source.name)")
        do {
            let first = try formatSource(source.lines, profile)
            formatted += first.lines
            do {
                let second = try formatSource(first.lines, profile)
                if first.lines == second.lines {
                    idempotency.append("\(source.name): stable")
                }
                else {
                    let index = zip(first.lines, second.lines).enumerated().first {
                        $0.element.0 != $0.element.1
                    }?.offset ?? min(first.lines.count, second.lines.count)
                    idempotency.append("\(source.name): unstable at line \(index + 1)")
                }
            } catch let error as SourceError {
                idempotency.append("\(source.name): unstable (second pass: \(error.line):\(error.column): \(error.message))")
            }
            catch {
                preconditionFailure()
            }
            let width = profile.number("width")
            for (i, line) in first.lines.enumerated() where line.count > width {
                diagnostics.append("\(source.name):\(i + 1): warning: line too long (\(line.count) > \(width))")
            }
            let longest = first.lines.map(\.count).max() ?? 0, broken = first.modes.values.filter {
                $0 != "flat"
            }.count, forced = first.modes.values.filter {
                $0 == "forced"
            }.count
            docTree.append("metrics lines=\(first.lines.count) longest=\(longest) comments=\(first.comments) groups=\(first.modes.count) broken=\(broken) forced=\(forced)")
            if let (name, document) = first.firstFunction {
                docTree.append("function \(name)");
                Report.tree(document, 0, first.modes, &docTree)
            }
            else {
                docTree.append("no function")
            }
            changes += Report.diff(original, first.lines)
        } catch let error as SourceError {
            formatted += original;
            idempotency.append("\(source.name): skipped (syntax error)")
            diagnostics.append("\(source.name):\(error.line):\(error.column): error: \(error.message)")
            docTree.append("syntax error");
            changes.append("skipped (syntax error)")
        } catch {
            preconditionFailure()
        }
    }
    if diagnostics.isEmpty {
        diagnostics.append("no diagnostics")
    }
    write("formatted.txt", formatted);
    write("idempotency.txt", idempotency);
    write("diagnostics.txt", diagnostics);
    write("doc_tree.txt", docTree);
    write("changes.txt", changes)
}
runProgram()

struct SyntaxNode {
    let kind: String, tokens: [Int], children: [SyntaxNode], start: Int, end: Int
    var trailing: Int?
    init(_ kind: String, _ tokens: [Int], _ children: [SyntaxNode], _ start: Int, _ end: Int) {
        self.kind = kind;
        self.tokens = tokens;
        self.children = children;
        self.start = start;
        self.end = end
    }
}
final class Parser {
    let tokens: [Token]
    var index = 0
    init(_ tokens: [Token]) {
        self.tokens = tokens
    }
    static func isType(_ text: String) -> Bool {
        ["int", "float", "bool", "string", "void"].contains(text)
    }
    static func precedence(_ text: String) -> Int {
        switch text {
            case "||": return 1;
            case "&&": return 2;
            case "==", "!=": return 3;
            case "<", "<=", ">", ">=": return 4;
            case "+", "-": return 5;
            case "*", "/", "%": return 6;
            default: return 0
        }
    }
    var peek: Token {
        tokens[index]
    }
    var text: String {
        peek.text
    }
    func take() -> Int {
        let i = index;
        index += 1;
        return i
    }
    func error(_ expected: String) -> SourceError {
        SourceError(line: peek.line, column: peek.column, message: "expected \(expected), found \(peek.kind == "end" ? "end of file" : "'\(text)'")")
    }
    func symbol(_ text: String) throws -> Int {
        if self.text != text {
            throw error("'\(text)'")
        };
        return take()
    }
    func identifier() throws -> Int {
        if peek.kind != "identifier" {
            throw error("identifier")
        };
        return take()
    }
    func readType() throws -> Int {
        if !Self.isType(text) {
            throw error("type")
        };
        return take()
    }
    func node(_ kind: String, _ tokens: [Int], _ children: [SyntaxNode], _ start: Int) -> SyntaxNode {
        SyntaxNode(kind, tokens, children, start, max(0, index - 1))
    }
    func empty() -> SyntaxNode {
        SyntaxNode("empty", [], [], index, index)
    }
    func list(_ kind: String, _ open: String, _ close: String, _ trailing: Bool) throws -> SyntaxNode {
        let start = index
        var tokens = [try symbol(open)], children: [SyntaxNode] = [], tail: Int?
        if text != close {
            children.append(try listElement(kind))
            while text == "," {
                let comma = take()
                if trailing && text == close {
                    tail = comma;
                    break
                }
                tokens.append(comma);
                children.append(try listElement(kind))
            }
        }
        tokens.append(try symbol(close))
        var result = node(kind, tokens, children, start)
        result.trailing = tail
        return result
    }
    func listElement(_ kind: String) throws -> SyntaxNode {
        if kind == "params" {
            let start = index, tokens = [try readType(), try identifier()]
            var children: [SyntaxNode] = []
            while text == "[" {
                let s = index, pair = [take(), try symbol("]")];
                children.append(node("dimension", pair, [], s))
            }
            return node("parameter", tokens, children, start)
        }
        return kind == "initlist" ? try initializer() : try expression()
    }
    func initializer() throws -> SyntaxNode {
        text == "{" ? try list("initlist", "{", "}", true) : try expression()
    }
    func declaration(_ semicolon: Bool) throws -> SyntaxNode {
        let start = index, tokens = [try readType(), try identifier()];
        return try declarationRest(start, tokens, semicolon)
    }
    func declarationRest(_ start: Int, _ original: [Int], _ semicolon: Bool) throws -> SyntaxNode {
        var tokens = original, children: [SyntaxNode] = []
        while text == "[" {
            let s = index, open = take()
            let content = text == "]" ? [] : [try expression()], close = try symbol("]")
            children.append(node("dimension", [open, close], content, s))
        }
        if text == "=" {
            tokens.append(take());
            children.append(try initializer())
        }
        if semicolon {
            tokens.append(try symbol(";"))
        }
        return node("decl", tokens, children, start)
    }
    func item() throws -> SyntaxNode {
        let start = index, tokens = [try readType(), try identifier()]
        if text == "(" {
            let parameters = try list("params", "(", ")", false), block = try self.block();
            return node("function", tokens, [parameters, block], start)
        }
        return try declarationRest(start, tokens, true)
    }
    func block() throws -> SyntaxNode {
        let start = index, open = try symbol("{")
        var statements: [SyntaxNode] = []
        while text != "}" && peek.kind != "end" {
            statements.append(try statement())
        }
        let close = try symbol("}")
        return node("block", [open, close], statements, start)
    }
    func statement() throws -> SyntaxNode {
        let start = index
        if text == "{" {
            return try block()
        }
        if Self.isType(text) {
            return try declaration(true)
        }
        switch text {
            case "if":
            let keyword = take(), open = try symbol("("), condition = try expression(), close = try symbol(")"), body = try statement()
            var tokens = [keyword, open, close], children = [condition, body]
            if text == "else" {
                tokens.append(take());
                children.append(try statement())
            }
            return node("if", tokens, children, start)
            case "while":
            let keyword = take(), open = try symbol("("), condition = try expression(), close = try symbol(")"), body = try statement()
            return node("while", [keyword, open, close], [condition, body], start)
            case "for":
            let keyword = take(), open = try symbol("("), initial: SyntaxNode
            if text == ";" {
                initial = empty()
            } else if Self.isType(text) {
                initial = try declaration(false)
            } else {
                initial = try simple()
            }
            let first = try symbol(";"), condition = text == ";" ? empty() : try expression(), second = try symbol(";"), update = text == ")" ? empty() : try simple(), close = try symbol(")"), body = try statement()
            return node("for", [keyword, open, first, second, close], [initial, condition, update, body], start)
            case "switch":
            let keyword = take(), open = try symbol("("), condition = try expression(), close = try symbol(")"), left = try symbol("{")
            var children = [condition]
            while text == "case" || text == "default" {
                let s = index, label = take(), kind = tokens[label].text
                var body: [SyntaxNode] = []
                if kind == "case" {
                    body.append(try expression())
                }
                let colon = try symbol(":")
                while !["case", "default", "}"].contains(text) && peek.kind != "end" {
                    body.append(try statement())
                }
                children.append(node(kind, [label, colon], body, s))
            }
            let right = try symbol("}")
            return node("switch", [keyword, open, close, left, right], children, start)
            case "return":
            let keyword = take(), children = text == ";" ? [] : [try expression()], semi = try symbol(";")
            return node("return", [keyword, semi], children, start)
            case "break", "continue": let keyword = take(), kind = tokens[keyword].text, semi = try symbol(";");
            return node(kind, [keyword, semi], [], start)
            default: let expression = try simple(), semi = try symbol(";");
            return node("statement", [semi], [expression], start)
        }
    }
    func simple() throws -> SyntaxNode {
        let start = index, left = try expression()
        if ["=", "+=", "-=", "*=", "/=", "%="].contains(text) {
            let op = take(), right = try expression();
            return node("assign", [op], [left, right], start)
        }
        return node("exprstmt", [], [left], start)
    }
    func expression() throws -> SyntaxNode {
        let start = index, condition = try binary(1)
        if text == "?" {
            let question = take(), yes = try expression(), colon = try symbol(":"), no = try expression();
            return node("conditional", [question, colon], [condition, yes, no], start)
        }
        return condition
    }
    func binary(_ precedence: Int) throws -> SyntaxNode {
        let start = index
        var left = precedence == 6 ? try unary() : try binary(precedence + 1)
        while Self.precedence(text) == precedence {
            let op = take(), right = precedence == 6 ? try unary() : try binary(precedence + 1);
            left = node("binary", [op], [left, right], start)
        }
        return left
    }
    func unary() throws -> SyntaxNode {
        let start = index
        if text == "-" || text == "!" {
            let op = take(), child = try unary();
            return node("unary", [op], [child], start)
        }
        var target = try primary()
        while true {
            switch text {
                case "(": let list = try self.list("args", "(", ")", false);
                target = node("call", [], [target, list], start)
                case "[": let open = take(), expression = try self.expression(), close = try symbol("]");
                target = node("index", [open, close], [target, expression], start)
                case ".": let dot = take(), name = try identifier();
                target = node("member", [dot, name], [target], start)
                default: return target
            }
        }
    }
    func primary() throws -> SyntaxNode {
        let start = index
        if ["identifier", "number", "string"].contains(peek.kind) || text == "true" || text == "false" {
            let token = take();
            return node("atom", [token], [], start)
        }
        if text == "(" {
            let open = take(), child = try expression(), close = try symbol(")");
            return node("paren", [open, close], [child], start)
        }
        throw error("expression")
    }
    static func parse(_ tokens: [Token]) throws -> [SyntaxNode] {
        let parser = Parser(tokens)
        var items: [SyntaxNode] = []
        while parser.peek.kind != "end" {
            items.append(try parser.item())
        }
        return items
    }
}

struct Command {
    let indent: Int, flat: Bool, document: Document
}
struct Printed {
    let lines: [String], modes: [Int: String]
}
enum Printer {
    static func fits(_ remaining: Int, _ first: Command, _ stack: [Command]) -> Bool {
        if remaining < 0 {
            return false
        }
        var remaining = remaining, check = stack + [first]
        while let command = check.popLast() {
            let i = command.indent, flat = command.flat, document = command.document
            switch document {
                case .text(let string): remaining -= string.count
                case .ifBreak(let a, let b): remaining -= flat ? b.count : a.count
                case .line: if flat {
                    remaining -= 1
                } else {
                    return true
                }
                case .softline: if !flat {
                    return true
                }
                case .hardline: return true
                case .concat(let parts): for part in parts.reversed() {
                    check.append(Command(indent: i, flat: flat, document: part))
                }
                case .group(_, let child): check.append(Command(indent: i, flat: document.forced ? false : flat, document: child))
                case .nest(_, let child), .align(let child): check.append(Command(indent: i, flat: flat, document: child))
                default: break
            }
            if remaining < 0 {
                return false
            }
        }
        return true
    }
    static func print(_ document: Document, _ width: Int, _ column: Int) -> Printed {
        var stack = [Command(indent: 0, flat: false, document: document)], lines: [String] = [], modes: [Int: String] = [:], current = "", col = 0, pending: [String] = []
        func finalize() {
            var line = Lexer.trim(current)
            if !pending.isEmpty {
                let comment = pending.joined(separator: " ")
                if column > 0 && line.count < column - 1 && column - 1 + comment.count <= width {
                    line += String(repeating: " ", count: column - 1 - line.count)
                }
                else {
                    line += " "
                }
                line += comment;
                pending = []
            }
            lines.append(line)
        }
        while let command = stack.popLast() {
            let i = command.indent, flat = command.flat, document = command.document
            switch document {
                case .text(let string): current += string;
                col += string.count
                case .ifBreak(let a, let b): let string = flat ? b : a;
                current += string;
                col += string.count
                case .line, .softline, .hardline:
                let newline: Bool
                if case .hardline = document {
                    newline = true
                } else {
                    newline = !flat
                }
                if newline {
                    finalize();
                    current = String(repeating: " ", count: i);
                    col = i
                }
                else if case .line = document {
                    current += " ";
                    col += 1
                }
                case .concat(let parts): for part in parts.reversed() {
                    stack.append(Command(indent: i, flat: flat, document: part))
                }
                case .nest(let n, let child): stack.append(Command(indent: i + n, flat: flat, document: child))
                case .align(let child): stack.append(Command(indent: col, flat: flat, document: child))
                case .suffix(let string): pending.append(string)
                case .breakParent: break
                case .group(let id, let child):
                let mode = flat ? "flat" : document.forced ? "forced" : fits(width - col, Command(indent: i, flat: true, document: child), stack) ? "flat" : "break"
                modes[id] = mode;
                stack.append(Command(indent: i, flat: mode == "flat", document: child))
            }
        }
        finalize()
        return Printed(lines: lines, modes: modes)
    }
}

enum Report {
    static func tree(_ document: Document, _ depth: Int, _ modes: [Int: String], _ out: inout [String]) {
        let prefix = String(repeating: " ", count: depth * 2)
        switch document {
            case .concat(let parts): for part in parts {
                tree(part, depth, modes, &out)
            }
            case .text(let string): out.append(prefix + "text \"\(string)\"")
            case .suffix(let string): out.append(prefix + "suffix \"\(string)\"")
            case .ifBreak(let a, let b): out.append(prefix + "if_break \"\(a)\" \"\(b)\"")
            case .group(let id, let child): out.append(prefix + "group \(modes[id]!)");
            tree(child, depth + 1, modes, &out)
            case .nest(let n, let child): out.append(prefix + "nest \(n)");
            tree(child, depth + 1, modes, &out)
            case .align(let child): out.append(prefix + "align");
            tree(child, depth + 1, modes, &out)
            case .line: out.append(prefix + "line")
            case .softline: out.append(prefix + "softline")
            case .hardline: out.append(prefix + "hardline")
            case .breakParent: out.append(prefix + "break_parent")
        }
    }
    static func diff(_ a: [String], _ b: [String]) -> [String] {
        let n = a.count, m = b.count
        var lcs = Array(repeating: Array(repeating: 0, count: m + 1), count: n + 1)
        for i in (0..<n).reversed() {
            for j in (0..<m).reversed() {
                lcs[i][j] = a[i] == b[j] ? lcs[i + 1][j + 1] + 1 : max(lcs[i + 1][j], lcs[i][j + 1])
            }
        }
        var i = 0, j = 0, deleted = 0, inserted = 0, hunks: [(Int, Int, Int, Int, [String])] = []
        while i < n || j < m {
            if i < n && j < m && a[i] == b[j] {
                i += 1;
                j += 1;
                continue
            }
            let i0 = i, j0 = j
            var d = 0, e = 0, lines: [String] = []
            while i < n || j < m {
                if i < n && j < m && a[i] == b[j] {
                    break
                }
                if j == m || i < n && lcs[i + 1][j] >= lcs[i][j + 1] {
                    lines.append("-" + a[i]);
                    i += 1;
                    d += 1
                }
                else {
                    lines.append("+" + b[j]);
                    j += 1;
                    e += 1
                }
            }
            deleted += d;
            inserted += e;
            hunks.append((i0, j0, d, e, lines))
        }
        var result = ["hunks=\(hunks.count) deleted=\(deleted) inserted=\(inserted)"]
        for (i, j, d, e, lines) in hunks {
            result.append("@@ -\(d > 0 ? i + 1 : i),\(d) +\(e > 0 ? j + 1 : j),\(e) @@");
            result += lines
        }
        return result
    }
}
